package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class UpperNumberLineTest {
 @Test public void earlyFreshQuestionsIncludeHundredScale(){Generator g=new Generator(new Random(127));List<String> recent=new ArrayList<>();Set<Integer> scales=new HashSet<>();var limits=GlobalCurriculum.limits("england-primary-2021-v1",NumberLineRelations.ID,3);for(int i=0;i<20;i++){Question q=g.next(NumberLineRelations.ID,recent,true,limits);recent.add(q.signature());scales.add((int)q.diagram.values[1]);}assertEquals(Set.of(1,10,100),scales);}
 @Test public void yearThreeExhaustsPublicWindowsAndAll1001Values(){Generator g=new Generator(new Random(127));var limits=GlobalCurriculum.limits("england-primary-2021-v1",NumberLineRelations.ID,3);List<String> recent=new ArrayList<>();Set<Integer> values=new HashSet<>(),steps=new HashSet<>();for(int i=0;i<2112;i++){Question q=g.next(NumberLineRelations.ID,recent,true,limits);assertFalse(recent.contains(q.signature()));recent.add(q.signature());int[] v=NumberLineRelations.read(q);assertNotNull(v);assertTrue(v[0]+10*v[1]<=1000);int expected=v[0]+v[1]*v[3];values.add(expected);steps.add(v[1]);q.answers=new String[]{"poison"};assertTrue(new Checker().check(q,List.of(),List.of(""+expected)).correct());assertFalse(HelpPlan.forQuestion(q).canTransfer());}assertEquals(1001,values.size());assertEquals(Set.of(1,10,100),steps);assertEquals(recent.get(0),g.next(NumberLineRelations.ID,recent,false,limits).signature());}
 @Test public void endpointsAndStudentFramesKeepPublicScale(){Question q=NumberLineRelations.make(0,100,10);q.answers=new String[]{"poison"};assertTrue(new Checker().check(q,List.of(),List.of("1000")).correct());NumberLineRelations.attach(q);HelpPlan p=HelpPlan.forQuestion(q);int[] expected={0,100,10,1000,1000};for(int i=0;i<5;i++){assertTrue(p.step(i).accepts(""+expected[i]));assertFalse(p.step(i).before.matches(".*\\d.*"));}assertFalse(p.canTransfer());q.diagram.values[0]=Integer.MAX_VALUE;assertNull(NumberLineRelations.read(q));q=NumberLineRelations.make(990,1,0);assertTrue(new Checker().check(q,List.of(),List.of("990")).correct());q.diagram.values[1]=100;assertNotNull(NumberLineRelations.read(q));q.diagram.values[1]=1000;assertNull(NumberLineRelations.read(q));Learning.Profile profile=new Learning.Profile();GlobalCurriculum.chooseCountry(profile,"GB");GlobalCurriculum.choosePack(profile,"england-primary-2021-v1");assertTrue(GlobalCurriculum.pack(profile).inGrade(NumberLineRelations.ID,3));}
}
